// Keeps old readers of Alicat.Read.* working during migration.
// Writes only good data, so readers never act on frozen values.
if (msg.alicat.quality !== 'good') {
    global.set('Alicat.Read.quality', msg.alicat.quality);
    return null;
}
const v = msg.payload;
global.set('Alicat.Read', {
    PSIG: v.gaugePressure,
    massFlow_Raw: -v.massFlow, // the old flow inverted the sign (scale -1); keep or drop deliberately
    setpoint: v.setpoint,
    ts: msg.alicat.ts,
    quality: 'good'
});
global.set('Alicat.StatusBuffer', {
    HLD: msg.alicat.status.flags.holding,
    EXH: msg.alicat.status.flags.exhausting
});
return null;

// Window and slope are based on msg.alicat.ts (reply time), not on sample counts.
const WINDOW_MS = 1000;
if (msg.topic === 'reset') { context.set('buf', []); return null; }
if (msg.alicat.quality !== 'good') return null;
const buf = (context.get('buf') || []).filter(p => msg.alicat.ts - p.t <= WINDOW_MS);
buf.push({ t: msg.alicat.ts, v: msg.payload.massFlow });
context.set('buf', buf);
const mean = buf.reduce((s, p) => s + p.v, 0) / buf.length;
const first = buf[0];
const dt = (msg.alicat.ts - first.t) / 1000;
const slope = dt > 0 ? (msg.payload.massFlow - first.v) / dt : 0;
return { topic: 'massFlow', payload: { mean, slope, samples: buf.length, units: msg.alicat.units.massFlow } };
